import{_ as l,l as i,o as e,c as s,v as r,p as n,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"缓冲区溢出直觉","description":"","frontmatter":{"title":"缓冲区溢出直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/buffer-overflow.md","filePath":"cs/buffer-overflow.md","lastUpdated":1789023840000}'),h={name:"cs/buffer-overflow.md"};function A(E,a,f,_,u,m){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="缓冲区溢出直觉" tabindex="-1">缓冲区溢出直觉 <a class="header-anchor" href="#缓冲区溢出直觉" aria-label="Permalink to &quot;缓冲区溢出直觉&quot;">​</a></h1><div class="epigraph"><p>定长缓冲与可变长输入一旦相遇，多出来的字节会改写相邻的控制数据；防御从语言与布局入手，而不是从「怎么写进那些字节」入手。</p><footer>—— 据 Anderson 对内存破坏；对照[调用约定与栈](/cs/calling-convention-stack)、[地址空间布局](/cs/addrspace-layout)</footer></div><p><a href="/cs/toctou">上一课</a>把授权收到矩阵与票。本课不重做 Lampson。缺口是：用户态进程里，C 一类语言把相邻对象放在同一地址空间，长度检查一旦缺失，写入可以越过对象边界，改掉返回地址、函数指针或堆元数据。<a href="/cs/calling-convention-stack">调用约定</a>已经说明栈上有保存的返回地址；本课只讲<strong>越界为何打破隔离</strong>，以及防御落在哪一层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/process-image">进程映像</a>把代码、堆、栈放在同一可写可读（历史上还可执行）的空间里。访问控制在系统调用边界检查；进程内部的数组写入内核看不见。缺口不是提供构造恶意输入的步骤，而是承认：完整性可以在指令级被破坏，CIA 的 I 在「程序仍在跑、系统调用仍合法」时已经失败。</p><p><span class="marginnote">本课不给出 payload、shellcode、ROP 序列或利用步骤。课程只需要：越界写控制数据 ⇒ 控制流不再等于源代码；后课 ASLR/NX 降低可利用性，不从根上消灭越界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>根因：语言不检查边界、或把不可信长度拷进定长缓冲。防御分层：用带边界的语言或检查过的库；编译器插入金丝雀；栈不可执行；地址随机化；隔离把高价值密钥放到别的进程。本课把这些列为机制名字，实现细节在下一课收 NX 与 ASLR。</p>',8)),(e(),n(d,null,{default:t(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEN%5B%22%E9%95%BF%E5%BA%A6%E6%9C%AA%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20OOB%5B%22%E8%B6%8A%E7%95%8C%E5%86%99%22%5D%0A%20%20OOB%20--%3E%20CF%5B%22%E6%8E%A7%E5%88%B6%E6%95%B0%E6%8D%AE%E8%A2%AB%E6%94%B9%22%5D%0A%20%20CF%20--%3E%20MIT%5B%22%E8%AF%AD%E8%A8%80%20%2F%20%E9%87%91%E4%B8%9D%E9%9B%80%20%2F%20NX%20%2F%20ASLR%22%5D%0A%20%20MIT%20--%3E%20NX%5B%22%E5%90%8E%E8%AF%BE%3A%20ASLR%20%E4%B8%8E%20NX%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制流完整性一旦失守，引用监视器看到的仍是「该进程的系统调用」——最小特权只能限制损坏半径，不能把错误流纠正回源码。这与<a href="/cs/race-critical">竞争与临界区</a>不同：那是交错，这是空间上的相邻破坏。堆与栈都有元数据，越界读则服务机密性失败（泄漏密钥），不必改控制流。</p><p>越界读可以只伤保密（把密钥打到输出），不必改控制流。完整与保密在此分叉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>严禁把本课读成利用手册。也不要把「只有网络服务会溢出」当定理：本地 setuid、解析文件格式同样。内存安全语言把这类错误从完整性轴上挪走，但运行时与 FFI 仍可能再引入。</p><p>整数溢出导致分配长度变短、随后拷贝仍按原长度走，是同一类空间错误的变体，机制仍是「长度与对象不一致」。后课默认：越界是完整性事故；NX 与 ASLR 是降低可利用性的布局与权限位，不是正确性证明。</p><p>空间安全与类型安全是语言层的完整。本课只要求系统课读者：控制数据与用户数据若相邻且未检查，规格上的隔离已经不够。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>本课不提供构造越界写入的步骤，只说明控制数据与缓冲相邻时完整轴如何失败。</p></li><li><p>后课 NX/ASLR 改页权限与可预测性，不证明没有越界。</p></li><li><p>授权矩阵管系统调用；进程内越界写可以改控制数据。</p></li><li><p>防御：安全语言、检查、金丝雀、不可执行栈、随机化、隔离。</p></li><li><p>ASLR 与 NX 如何改布局与页权限，下一课只讲机制。</p></li><li><p>出处：Anderson, <em>Security Engineering</em>；对照教材中的栈帧布局，不引用利用配方。</p></li></ul>',9))])}const b=l(h,[["render",A]]);export{S as __pageData,b as default};
